namespace ResearchAgent;

/// <summary>
/// In-memory notebook that stores research notes for the current session.
/// </summary>
public sealed class Notebook
{
    private readonly List<NoteEntry> _notes = [];

    public void Add(string title, string content, string? source = null)
    {
        _notes.Add(new NoteEntry(title, content, source, DateTime.UtcNow));
    }

    public IReadOnlyList<NoteEntry> GetAll() => _notes.AsReadOnly();

    public void Clear() => _notes.Clear();
}

public sealed record NoteEntry(string Title, string Content, string? Source, DateTime Timestamp);

using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent for searching the web and taking notes.
/// </summary>
public sealed class ResearchTools
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    private readonly Notebook _notebook;

    public ResearchTools(Notebook notebook) => _notebook = notebook;

    [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encodedQuery = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await HttpClient.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<object>();

            // Extract the abstract if available
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add(new { Title = abstractSource, Snippet = abstractText, Url = abstractUrl });
            }

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrEmpty(text))
                    {
                        results.Add(new { Title = text?[..Math.Min(text.Length, 80)], Snippet = text, Url = firstUrl });
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing the search query.";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title, content, and optional source URL. Use this to record key findings during research.")]
    public string TakeNote(
        [Description("A short title for the note")] string title,
        [Description("The content/finding to record")] string content,
        [Description("The source URL where this information was found")] string? source = null)
    {
        _notebook.Add(title, content, source);
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note saved: '{title}'. You now have {_notebook.GetAll().Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during this research session.")]
    public string GetNotes()
    {
        var notes = _notebook.GetAll();
        if (notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        var formatted = notes.Select((n, i) =>
            $"[{i + 1}] {n.Title}\n    {n.Content}" +
            (n.Source is not null ? $"\n    Source: {n.Source}" : ""));

        return string.Join("\n\n", formatted);
    }

    public void ClearNotes() => _notebook.Clear();
}

