arguments.new_str:
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notebook>();
builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var tools = new List<AITool>();
tools.AddRange(AIFunctionFactory.Create(researchTools.WebSearch));
tools.AddRange(AIFunctionFactory.Create(researchTools.TakeNote));
tools.AddRange(AIFunctionFactory.Create(researchTools.GetNotes));

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI research assistant that searches the web and takes notes.",
    instructions: "You are a research assistant. When given a topic, use the WebSearch tool to find "
        + "information from multiple angles. Use the TakeNote tool to record key findings as you go. "
        + "After gathering enough information (at least 3 searches), use GetNotes to review your notes, "
        + "then provide a comprehensive summary that synthesizes your findings. Always cite sources.",
    tools: tools);

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a detailed summary: {topic}"),
    };

    Console.WriteLine($"\nResearching '{topic}'...\n");

    var response = await agent.RunAsync(messages);

    foreach (var message in response.Messages)
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.WriteLine(message.Text);
        }
    }

    Console.WriteLine();
}

